  if(!Number.isFinite(L)||L<=fixed.minimumLength||!exact())throw new Error('Invalid 篒 browser length')
  const d=Math.min(progress*L,L),point=guide!.getPointAtLength(d)
  if(!Number.isFinite(point.x)||!Number.isFinite(point.y)||!exact())throw new Error('Changed 篒 guide or invalid endpoint')
